			'import * as React from "react";\nimport { ClipboardIcon, CopyIcon, ScissorsIcon, TrashIcon } from "lucide-react";\nimport { Button } from "@workspace/ui/components/button";\nimport {\n\tContextMenu,\n\tContextMenuContent,\n\tContextMenuGroup,\n\tContextMenuItem,\n\tContextMenuSeparator,\n\tContextMenuSub,\n\tContextMenuSubContent,\n\tContextMenuSubTrigger,\n\tContextMenuTrigger,\n} from "@workspace/ui/components/context-menu";\nimport { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@workspace/ui/components/dialog";\n\nexport function ContextMenu10Example(): React.JSX.Element {\n\treturn (\n\t\t<div className="flex w-full items-center justify-center p-12">\n\t\t\t<Dialog>\n\t\t\t\t<DialogTrigger render={<Button variant="outline" />}>Open Dialog</DialogTrigger>\n\t\t\t\t<DialogContent>\n\t\t\t\t\t<DialogHeader>\n\t\t\t\t\t\t<DialogTitle>Context Menu Example</DialogTitle>\n\t\t\t\t\t\t<DialogDescription>Right click on the area below to see the context menu.</DialogDescription>\n\t\t\t\t\t</DialogHeader>\n\t\t\t\t\t<ContextMenu>\n\t\t\t\t\t\t<ContextMenuTrigger className="flex aspect-[2/0.5] w-full items-center justify-center rounded-lg border border-dashed text-sm text-muted-foreground">\n\t\t\t\t\t\t\tRight click here\n\t\t\t\t\t\t</ContextMenuTrigger>\n\t\t\t\t\t\t<ContextMenuContent>\n\t\t\t\t\t\t\t<ContextMenuGroup>\n\t\t\t\t\t\t\t\t<ContextMenuItem>\n\t\t\t\t\t\t\t\t\t<CopyIcon />\n\t\t\t\t\t\t\t\t\tCopy\n\t\t\t\t\t\t\t\t</ContextMenuItem>\n\t\t\t\t\t\t\t\t<ContextMenuItem>\n\t\t\t\t\t\t\t\t\t<ScissorsIcon />\n\t\t\t\t\t\t\t\t\tCut\n\t\t\t\t\t\t\t\t</ContextMenuItem>\n\t\t\t\t\t\t\t\t<ContextMenuItem>\n\t\t\t\t\t\t\t\t\t<ClipboardIcon />\n\t\t\t\t\t\t\t\t\tPaste\n\t\t\t\t\t\t\t\t</ContextMenuItem>\n\t\t\t\t\t\t\t</ContextMenuGroup>\n\t\t\t\t\t\t\t<ContextMenuSeparator />\n\t\t\t\t\t\t\t<ContextMenuSub>\n\t\t\t\t\t\t\t\t<ContextMenuSubTrigger>More Options</ContextMenuSubTrigger>\n\t\t\t\t\t\t\t\t<ContextMenuSubContent>\n\t\t\t\t\t\t\t\t\t<ContextMenuGroup>\n\t\t\t\t\t\t\t\t\t\t<ContextMenuItem>Save Page...</ContextMenuItem>\n\t\t\t\t\t\t\t\t\t\t<ContextMenuItem>Create Shortcut...</ContextMenuItem>\n\t\t\t\t\t\t\t\t\t\t<ContextMenuItem>Name Window...</ContextMenuItem>\n\t\t\t\t\t\t\t\t\t</ContextMenuGroup>\n\t\t\t\t\t\t\t\t\t<ContextMenuSeparator />\n\t\t\t\t\t\t\t\t\t<ContextMenuGroup>\n\t\t\t\t\t\t\t\t\t\t<ContextMenuItem>Developer Tools</ContextMenuItem>\n\t\t\t\t\t\t\t\t\t</ContextMenuGroup>\n\t\t\t\t\t\t\t\t</ContextMenuSubContent>\n\t\t\t\t\t\t\t</ContextMenuSub>\n\t\t\t\t\t\t\t<ContextMenuSeparator />\n\t\t\t\t\t\t\t<ContextMenuGroup>\n\t\t\t\t\t\t\t\t<ContextMenuItem variant="destructive">\n\t\t\t\t\t\t\t\t\t<TrashIcon />\n\t\t\t\t\t\t\t\t\tDelete\n\t\t\t\t\t\t\t\t</ContextMenuItem>\n\t\t\t\t\t\t\t</ContextMenuGroup>\n\t\t\t\t\t\t</ContextMenuContent>\n\t\t\t\t\t</ContextMenu>\n\t\t\t\t</DialogContent>\n\t\t\t</Dialog>\n\t\t</div>\n\t);\n}\n',
